    /** Seed rows for one collection name (vehicles, customers or rentals). */
    public static function forCollection(string $collection): array
    {
        switch ($collection) {
            case 'vehicles':
                return self::vehicles();
            case 'customers':
                return self::customers();
            case 'rentals':
                return self::rentals();
        }
        return [];
    }
